package com.alpharip.staffmod.cases.caseredactiontool; public final class RedactionEntry {private final int start,end;private final String reason;private final boolean enabled;public RedactionEntry(int s,int e,String r,boolean on){if(s<0||e<=s)throw new IllegalArgumentException("Invalid range");start=s;end=e;reason=r==null?"":r;enabled=on;}public int getStart(){return start;}public int getEnd(){return end;}public String getReason(){return reason;}public boolean isEnabled(){return enabled;}}